import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"Configuration File","description":"","frontmatter":{},"headers":[],"relativePath":"advanced-usage/configuration-file.md","filePath":"en/advanced-usage/configuration-file.md","lastUpdated":1785978782000}'),t={name:"advanced-usage/configuration-file.md"};function o(l,s,p,d,r,h){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="configuration-file" tabindex="-1">Configuration File <a class="header-anchor" href="#configuration-file" aria-label="Permalink to &quot;Configuration File&quot;">​</a></h1><p>Instead of passing every option to <code>withSidebar</code> or <code>generateSidebar</code>, you can place a <code>sidebar.config.json</code> file in your project and let VitePress Sidebar pick it up automatically.</p><p>A configuration file applies to the folder it lives in <strong>and to every subfolder below it</strong>, so each part of your documentation can define its own rules. Options declared closer to a document always win, much like a nested <code>tsconfig.json</code>.</p><p>The file name is fixed. <code>sidebar.config.json</code> is the only name that is recognized.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><p>Create a <code>sidebar.config.json</code> next to your documents:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/sidebar.config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capitalizeFirst&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;useTitleFromFileHeading&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>With the file above in place, this is all you need in your VitePress config:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/.vitepress/config.mjs</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vitepress&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { withSidebar } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vitepress-sidebar&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withSidebar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ title: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;My Docs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }));</span></span></code></pre></div><h2 id="overriding-options-per-folder" tabindex="-1">Overriding options per folder <a class="header-anchor" href="#overriding-options-per-folder" aria-label="Permalink to &quot;Overriding options per folder&quot;">​</a></h2><p>Assume a project like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├─ sidebar.config.json        &lt;-- applies to everything below \`docs\`</span></span>
<span class="line"><span>├─ index.md</span></span>
<span class="line"><span>├─ guide/</span></span>
<span class="line"><span>│  ├─ one.md</span></span>
<span class="line"><span>│  └─ two.md</span></span>
<span class="line"><span>└─ api/</span></span>
<span class="line"><span>   ├─ sidebar.config.json     &lt;-- applies to everything below \`api\`</span></span>
<span class="line"><span>   ├─ three.md</span></span>
<span class="line"><span>   └─ internal/</span></span>
<span class="line"><span>      └─ four.md</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/sidebar.config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sortMenusByName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/api/sidebar.config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sortMenusOrderByDescending&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;excludeByGlobPattern&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;internal/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>guide</code> folder is collapsed and sorted by name, while the <code>api</code> folder is expanded, sorted in reverse and hides its <code>internal</code> directory. Every option that <code>docs/api/sidebar.config.json</code> does not declare is inherited from <code>docs/sidebar.config.json</code>.</p><p>Note that paths in <code>excludeByGlobPattern</code> are relative to the folder that owns the configuration file, not to <code>documentRootPath</code>.</p><h2 id="describing-the-folder-itself" tabindex="-1">Describing the folder itself <a class="header-anchor" href="#describing-the-folder-itself" aria-label="Permalink to &quot;Describing the folder itself&quot;">​</a></h2><p>Everything above decides how the <strong>contents</strong> of a folder are generated. The <code>$folder</code> key describes the folder as it appears in the sidebar, and applies to that one folder only. Subfolders never inherit it.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/guide/sidebar.config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$folder&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Getting Started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/guide/install&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>order</code></td><td><code>number</code></td><td>Position of the folder among its siblings. Read when <a href="/guide/options#sortmenusbyfrontmatterorder">sortMenusByFrontmatterOrder</a> is enabled.</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>Menu title of the folder.</td></tr><tr><td><code>link</code></td><td><code>string</code></td><td>Page the folder links to.</td></tr></tbody></table><p>Without <code>$folder</code>, a folder can only be named, linked and ordered through the <code>index.md</code> it contains, which has two consequences:</p><ul><li>A folder needs an <code>index.md</code> even when it has no page of its own to show.</li><li>The <code>order</code> of that <code>index.md</code> decides both where the folder sits among its siblings <strong>and</strong> where the <code>index.md</code> sits inside the folder, so the two cannot be chosen independently.</li></ul><p><code>$folder</code> removes both limits:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├─ guide/</span></span>
<span class="line"><span>│  ├─ sidebar.config.json     { &quot;$folder&quot;: { &quot;order&quot;: 1 } }</span></span>
<span class="line"><span>│  ├─ index.md                order: 1</span></span>
<span class="line"><span>│  └─ install.md              order: 2</span></span>
<span class="line"><span>└─ api/</span></span>
<span class="line"><span>   ├─ sidebar.config.json     { &quot;$folder&quot;: { &quot;order&quot;: 2, &quot;text&quot;: &quot;API&quot;, &quot;link&quot;: &quot;/api/reference&quot; } }</span></span>
<span class="line"><span>   └─ reference.md</span></span></code></pre></div><p><code>guide</code> comes first and <code>api</code> second, while <code>guide/index.md</code> stays at the top of its own folder. <code>api</code> is ordered, named and linked without holding an <code>index.md</code> at all.</p><p>A value declared in <code>$folder</code> always wins over the one taken from the folder name or from <code>index.md</code>. Since a folder at or above the document root is not a sidebar entry, <code>$folder</code> is ignored (with a warning) in a configuration file placed there.</p><h2 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to &quot;Priority&quot;">​</a></h2><p>Options are merged in the following order, where a later entry overrides an earlier one:</p><ol><li>Options passed to <code>withSidebar</code> or <code>generateSidebar</code></li><li><code>sidebar.config.json</code> of the parent folders, from the shallowest to the deepest</li><li><code>sidebar.config.json</code> of the folder itself</li></ol><p>In other words, a configuration file always takes priority over the options you pass as an argument.</p><h2 id="automatic-documentrootpath" tabindex="-1">Automatic <code>documentRootPath</code> <a class="header-anchor" href="#automatic-documentrootpath" aria-label="Permalink to &quot;Automatic \`documentRootPath\`&quot;">​</a></h2><p>When you do not pass <code>documentRootPath</code>, it is derived from where the configuration files are: the closest common parent directory of every <code>sidebar.config.json</code> found in the project becomes the document root.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/</span></span>
<span class="line"><span>├─ package.json</span></span>
<span class="line"><span>├─ src/</span></span>
<span class="line"><span>└─ docs/                      &lt;-- \`documentRootPath\` becomes \`/docs\`</span></span>
<span class="line"><span>   ├─ sidebar.config.json</span></span>
<span class="line"><span>   ├─ .vitepress/</span></span>
<span class="line"><span>   └─ index.md</span></span></code></pre></div><p>If you prefer to keep the configuration file in the project root, declare the path explicitly. <code>documentRootPath</code> is only read from a <code>sidebar.config.json</code> that sits in the directory VitePress is run from:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// sidebar.config.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;documentRootPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Directories such as <code>node_modules</code>, <code>dist</code>, <code>build</code>, <code>out</code>, <code>coverage</code>, <code>target</code>, <code>vendor</code> and any directory whose name starts with a dot are skipped while searching for configuration files.</p><h2 id="options-that-cannot-be-used-in-every-folder" tabindex="-1">Options that cannot be used in every folder <a class="header-anchor" href="#options-that-cannot-be-used-in-every-folder" aria-label="Permalink to &quot;Options that cannot be used in every folder&quot;">​</a></h2><p>Some options describe the sidebar as a whole rather than a single folder. They are only read from configuration files located between the directory VitePress is run from and the scan root, and are ignored (with a warning) in any file below it:</p><ul><li><a href="/guide/options#documentrootpath">documentRootPath</a></li><li><a href="/guide/options#scanstartpath">scanStartPath</a></li><li><a href="/guide/options#resolvepath">resolvePath</a></li><li><a href="/guide/options#basepath">basePath</a></li><li><a href="/guide/options#rootgrouptext">rootGroupText</a></li><li><a href="/guide/options#rootgrouplink">rootGroupLink</a></li><li><a href="/guide/options#rootgroupcollapsed">rootGroupCollapsed</a></li><li><a href="/guide/options#includerootindexfile">includeRootIndexFile</a></li><li><a href="/guide/options#includedynamicroutes">includeDynamicRoutes</a></li><li><a href="/guide/options#removeprefixafterordering">removePrefixAfterOrdering</a></li><li><a href="/guide/options#debugprint">debugPrint</a></li></ul><p>Any key that is not a VitePress Sidebar option is ignored with a warning as well, and so is a value of the wrong type, so a mistake never changes the result silently:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collapsed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ignored: must be a boolean</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;excludeByGlobPattern&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ignored: must be an array of strings</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sortFolderTo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;up&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // ignored: must be one of &#39;top&#39;, &#39;bottom&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A <code>null</code> value is always accepted and leaves the option unset. The <code>$schema</code> key is always allowed as well, which lets your editor attach a JSON schema.</p><p>An option whose value is a function, such as <a href="/guide/options#sortmenusbycustomfunction">sortMenusByCustomFunction</a>, has no representation in JSON and is therefore treated as an unknown key. Pass it as an argument instead.</p><h2 id="multiple-sidebars" tabindex="-1">Multiple sidebars <a class="header-anchor" href="#multiple-sidebars" aria-label="Permalink to &quot;Multiple sidebars&quot;">​</a></h2><p>Configuration files work with <a href="/advanced-usage/multiple-sidebars-how-to">multiple sidebars</a> too. Each entry of the array resolves its own configuration files, and a file placed in the directory a sidebar starts scanning from acts as the root configuration for that sidebar.</p>`,45)])])}const u=i(t,[["render",o]]);export{k as __pageData,u as default};
